using System;
using System.Diagnostics;
using System.IO;
using System.Runtime.InteropServices;
using System.Runtime.InteropServices.ComTypes;
using System.Threading;
class HostSmoke {
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS "+name);}
 static void Wait(dynamic bridge){for(int i=0;i<600;i++){Thread.Sleep(100);if(!bridge.IsBusy){Console.WriteLine("Scan: "+bridge.Status);return;}}throw new TimeoutException("Host analysis timeout");}
 static void Analyze(dynamic bridge){bridge.Analyze();Wait(bridge);}
 [DllImport("ole32.dll")]static extern int GetRunningObjectTable(int r,out IRunningObjectTable t);
 [DllImport("ole32.dll")]static extern int CreateBindCtx(int r,out IBindCtx c);
 static object Find(string filename){IRunningObjectTable table;IBindCtx context;GetRunningObjectTable(0,out table);CreateBindCtx(0,out context);IEnumMoniker list;table.EnumRunning(out list);var values=new IMoniker[1];try{while(list.Next(1,values,IntPtr.Zero)==0){string name;values[0].GetDisplayName(context,null,out name);if(String.Equals(name,filename,StringComparison.OrdinalIgnoreCase)){object result;table.GetObject(values[0],out result);return result;}Marshal.ReleaseComObject(values[0]);}return null;}finally{Marshal.ReleaseComObject(list);Marshal.ReleaseComObject(context);Marshal.ReleaseComObject(table);}}
 [STAThread]static int Main(string[] args){dynamic book=null,app=null;Process process=null;try{string filename=Path.GetFullPath("vsto/tests/fixtures/host-"+Guid.NewGuid().ToString("N")+".xlsx");File.Copy("test-workbooks/integration.xlsx",filename);var info=new ProcessStartInfo(@"C:\Program Files\Microsoft Office\Root\Office16\EXCEL.EXE","/x /r \""+filename+"\""){UseShellExecute=false,WindowStyle=ProcessWindowStyle.Hidden};info.EnvironmentVariables["VSTO_SUPPRESSDISPLAYALERTS"]="1";info.EnvironmentVariables["VSTO_LOGALERTS"]="1";process=Process.Start(info);for(int i=0;i<120;i++){Thread.Sleep(250);book=Find(filename);if((object)book!=null)break;}if((object)book==null)throw new Exception("Test workbook did not register in ROT");app=book.Application;app.DisplayAlerts=false;Console.WriteLine("Excel workbook attached");foreach(dynamic add in app.COMAddIns)Console.WriteLine(add.ProgId+" "+add.Connect);dynamic monja=app.COMAddIns.Item("Monja");Console.WriteLine("Connected="+monja.Connect);if(!monja.Connect)monja.Connect=true;dynamic bridge=monja.Object;Console.WriteLine("Ready="+bridge.Ready+" Version="+bridge.Version);if(!bridge.Ready)throw new Exception("Add-in not ready");if(args.Length>0&&args[0]=="--ui"){app.Visible=true;Console.WriteLine("NATIVE_UI_READY "+book.Name);string last="";for(int tick=0;tick<240;tick++){Thread.Sleep(500);string current="visible="+bridge.PaneVisible+" count="+bridge.ResultCount+" busy="+bridge.IsBusy+" status="+bridge.Status;if(current!=last){Console.WriteLine(current);last=current;}if(File.Exists("dist/verification/vsto/end-native-ui"))break;}return 0;}bridge.Show();Console.WriteLine("PaneVisible="+bridge.PaneVisible);
Wait(bridge);Check(bridge.ResultCount>=4,"opening all dependencies starts initial analysis");string csv=bridge.Csv;
Check(bridge.ResultCount>=4 && csv.Contains("formula")&&csv.Contains("chart")&&csv.Contains("pivot"),"VSTO pane formula/chart/pivot results");
int total=bridge.ResultCount;string[] records=csv.Split(new[]{"\r\n","\n"},StringSplitOptions.RemoveEmptyEntries);for(int row=1;row<records.Length;row++){if(records[row].StartsWith("\"chart\"")){bridge.Go(row-1,true);Check((object)app.ActiveChart!=null,"VSTO chart navigation");break;}}bridge.Show();for(int row=1;row<records.Length;row++){if(records[row].StartsWith("\"pivot\"")){bridge.Go(row-1,true);Check(app.Selection.Address[false,false,1]=="H5","VSTO pivot navigation");break;}}bridge.Show();dynamic input=book.Worksheets.Item["入力"];input.Activate();input.Range["B2"].Select();
bridge.Impact(true,false);Check(bridge.ResultCount>=3,"VSTO selected-cell dependents");
bridge.Go(0,false);Check(app.Selection.Worksheet.Name=="入力" && app.Selection.Row<=2 && app.Selection.Row+app.Selection.Rows.Count>2,"VSTO navigate source range");
bridge.Language(true);Check(bridge.ResultCount>=3,"English switch preserves impact mode");bridge.Language(false);
dynamic summary=book.Worksheets.Item["集計"];summary.Activate();summary.Range["D10"].Select();bridge.Impact(false,false);
Check(bridge.ResultCount==1,"VSTO selected-cell precedents");Check(((string)bridge.Status).StartsWith("表示 1件"),"displayed count follows the selected-cell filter");bridge.Go(0,true);Check(app.Selection.Address[false,false,1]=="D10","VSTO navigate consumer cell");
bridge.Show();dynamic second=app.Workbooks.Add();try{second.Worksheets.Item[1].Range["A1"].Formula="='["+book.Name+"]入力'!B2";Analyze(bridge);Check(bridge.ResultCount>total&&bridge.Csv.Contains((string)second.Name),"VSTO newly created second workbook included");}finally{second.Close(false);}bridge.Show();Wait(bridge);return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{if((object)book!=null)book.Close(false);if((object)app!=null)app.Quit();}}
}
